create table buyer_companies (created_at datetime(6) not null, id bigint not null auto_increment, updated_at datetime(6) not null, ruc varchar(11) not null, phone varchar(30), sector varchar(100), contact_email varchar(150), name varchar(150) not null, address varchar(255), primary key (id)) engine=InnoDB;
create table deliveries (created_at datetime(6) not null, delivered_at datetime(6), dispatched_at datetime(6), driver_id bigint not null, id bigint not null auto_increment, order_id bigint not null, provider_id bigint not null, updated_at datetime(6) not null, vehicle_id bigint not null, notes TEXT, scheduled_date varchar(255), status enum ('DELIVERED','DISPATCHED','FAILED','SCHEDULED') not null, primary key (id)) engine=InnoDB;
create table drivers (created_at datetime(6) not null, id bigint not null auto_increment, provider_id bigint not null, updated_at datetime(6) not null, phone_number varchar(30) not null, status varchar(30) not null, license_number varchar(60) not null, first_name varchar(80) not null, last_name varchar(80) not null, email varchar(160) not null, primary key (id)) engine=InnoDB;
create table equipment (auto_refill bit, current_level float(53) not null, refill_threshold integer, tank_capacity float(53) not null, company_id bigint not null, created_at datetime(6) not null, favorite_provider_id bigint, id bigint not null auto_increment, updated_at datetime(6) not null, last_refill_date varchar(255), license_plate varchar(255) not null, location varchar(255), name varchar(255) not null, status varchar(255), equipment_type enum ('BUS','EXCAVATOR','FORKLIFT','GENERATOR','OTHER','TRUCK') not null, fuel_type VARCHAR(20) not null, primary key (id)) engine=InnoDB;
create table fuel_orders (requested_quantity float(53) not null, scheduled_date date, total_price float(53) not null, company_id bigint not null, created_at datetime(6) not null, equipment_id bigint, fuel_product_id bigint not null, id bigint not null auto_increment, provider_id bigint not null, request_id bigint, updated_at datetime(6) not null, status VARCHAR(30) not null, delivery_address varchar(255) not null, primary key (id)) engine=InnoDB;
create table fuel_products (active bit, available_stock float(53) not null, capacity float(53), price_per_unit float(53) not null, created_at datetime(6) not null, id bigint not null auto_increment, provider_id bigint not null, updated_at datetime(6) not null, name varchar(255) not null, unit varchar(255) not null, fuel_type VARCHAR(20) not null, primary key (id)) engine=InnoDB;
create table fuel_requests (delivery_date date not null, quantity float(53) not null, unit_price float(53) not null, buyer_company_id bigint not null, created_at datetime(6) not null, equipment_id bigint, fuel_product_id bigint not null, id bigint not null auto_increment, provider_id bigint not null, updated_at datetime(6) not null, source varchar(20) not null, unit varchar(20) not null, fuel_type varchar(30) not null, rejection_reason varchar(240), delivery_address varchar(255) not null, product_name varchar(255) not null, status enum ('APPROVED','PENDING','REJECTED') not null, primary key (id)) engine=InnoDB;
create table notifications (is_read bit not null, created_at datetime(6) not null, id bigint not null auto_increment, reference_id bigint, updated_at datetime(6) not null, user_id bigint not null, type VARCHAR(40) not null, message TEXT not null, title varchar(255) not null, primary key (id)) engine=InnoDB;
create table password_reset_tokens (expires_at datetime(6) not null, id bigint not null auto_increment, user_id bigint not null, token_hash varchar(64) not null, primary key (id)) engine=InnoDB;
create table payments (amount float(53) not null, company_id bigint not null, created_at datetime(6) not null, id bigint not null auto_increment, order_id bigint not null, paid_at datetime(6), updated_at datetime(6) not null, transaction_reference varchar(255), payment_method enum ('BANK_TRANSFER','CASH','CREDIT_CARD','DEBIT_CARD') not null, status enum ('COMPLETED','FAILED','PENDING','REFUNDED') not null, primary key (id)) engine=InnoDB;
create table provider_companies (rating float(53), created_at datetime(6) not null, id bigint not null auto_increment, updated_at datetime(6) not null, ruc varchar(11) not null, phone varchar(30), name varchar(150) not null, description varchar(500), address varchar(255), primary key (id)) engine=InnoDB;
create table provider_company_fuel_types (provider_company_id bigint not null, fuel_type varchar(20)) engine=InnoDB;
create table provider_ratings (rating integer not null, company_id bigint not null, created_at datetime(6) not null, id bigint not null auto_increment, provider_id bigint not null, updated_at datetime(6) not null, primary key (id)) engine=InnoDB;
create table roles (id bigint not null auto_increment, name enum ('ROLE_BUYER','ROLE_PROVIDER') not null, primary key (id)) engine=InnoDB;
create table user_roles (role_id bigint not null, user_id bigint not null, primary key (role_id, user_id)) engine=InnoDB;
create table users (company_id bigint, created_at datetime(6) not null, id bigint not null auto_increment, provider_id bigint, updated_at datetime(6) not null, username varchar(100) not null, password varchar(120) not null, primary key (id)) engine=InnoDB;
create table vehicles (capacity float(53) not null, created_at datetime(6) not null, id bigint not null auto_increment, provider_id bigint not null, updated_at datetime(6) not null, license_plate varchar(20) not null, unit varchar(20) not null, status varchar(30) not null, brand varchar(80) not null, model varchar(80) not null, primary key (id)) engine=InnoDB;
